{
  "items": [
    {
      "title": "German Longitudinal Election Study (GLES), 2009–2019",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "One of the most relevant datasets for studying political behaviour and attitudes in Germany during the 2010s. The GLES provides comprehensive survey data on German federal elections, particularly the 2013 and 2017 elections. It covers voting behaviour, party identification, political preferences, electoral participation, political trust, campaign effects, and attitudes toward political candidates. Its cross-sectional and longitudinal components allow researchers to examine changes in electoral behaviour and political attitudes over time."
    },
    {
      "title": "German General Social Survey (ALLBUS), 2010–2018",
      "url_or_doi": "https://www.gesis.org/en/allbus/data-and-documentation",
      "justification": "ALLBUS is a nationally representative survey conducted approximately every two years in Germany. The 2010, 2012, 2014, 2016, and 2018 waves provide extensive information on political attitudes, democratic values, political participation, social trust, immigration attitudes, and ideological orientations. The dataset is especially useful for investigating changes in German political culture, differences between eastern and western Germany, and relationships between socioeconomic characteristics and political preferences."
    },
    {
      "title": "Politbarometer, 1977–2024 (Partial Cumulation)",
      "url_or_doi": "https://doi.org/10.4232/1.14611",
      "justification": "The Politbarometer is a recurring public opinion survey conducted by Forschungsgruppe Wahlen for German public broadcaster ZDF. Its cumulative dataset includes observations throughout 2010–2019, covering voting intentions, party preferences, political interest, satisfaction with democracy, evaluations of political leaders, and perceptions of government performance. Its frequent measurements make it particularly valuable for analysing short-term changes in political opinion and longer-term trends during the Merkel era."
    },
    {
      "title": "Politbarometer 2019 (Cumulated Data Set)",
      "url_or_doi": "https://doi.org/10.4232/1.13603",
      "justification": "This dataset combines Politbarometer surveys conducted throughout 2019. It contains detailed information on voting intentions, party evaluations, political satisfaction, public perceptions of immigration and asylum policies, climate change, European integration, and attitudes toward the Alternative for Germany (AfD). It is especially relevant for studying political polarisation, populism, and party competition in Germany at the end of the 2010s."
    },
    {
      "title": "GLES Tracking Surveys, 2009–2026 (Cumulation)",
      "url_or_doi": "https://search.gesis.org/research_data/ZA6832",
      "justification": "The GLES Tracking Surveys provide repeated measurements of political opinions and electoral preferences in Germany. Researchers can select observations from 2010–2019 to investigate changes in party support, voting intentions, political evaluations, and issue preferences. The dataset is particularly useful for analysing the development of German electoral competition between federal elections and examining shifts in political attitudes surrounding the emergence of the AfD."
    },
    {
      "title": "European Social Survey (ESS), Germany, Rounds 5–9 (2010–2019)",
      "url_or_doi": "https://www.europeansocialsurvey.org/",
      "justification": "The European Social Survey provides high-quality comparative survey data on political and social attitudes across European countries, including Germany. Rounds 5–9 cover the 2010s and contain measures of political interest, institutional trust, satisfaction with democracy, electoral participation, immigration attitudes, ideological self-placement, and social values. German observations can be analysed independently or compared with other European countries to understand developments in political trust, democratic legitimacy, and political polarisation."
    },
    {
      "title": "ARD-DeutschlandTREND, Surveys from 2010–2019",
      "url_or_doi": "https://search.gesis.org/?study_group=ARD-DeutschlandTrend&type=research_data",
      "justification": "ARD-DeutschlandTREND is a recurring German public opinion survey that provides information on voting intentions, evaluations of government performance, political leadership, and public attitudes toward major political issues. Surveys conducted during the 2010s are particularly useful for examining reactions to the Eurozone crisis, the 2015 refugee crisis, changes in support for established political parties, and the rise of right-wing populism. The GESIS catalogue provides access to individual survey datasets."
    },
    {
      "title": "GESIS Panel, Longitudinal Core Studies, 2014–2019",
      "url_or_doi": "https://www.gesis.org/en/gesis-panel/documentation/longitudinal-core-studies-gppop",
      "justification": "The GESIS Panel is a probability-based longitudinal survey infrastructure that began collecting data during the 2010s. Its 2014–2019 waves include measures relating to social and political participation, attitudes, and demographic characteristics. The panel structure enables researchers to investigate changes in individual political opinions over time and assess relationships between social characteristics, political engagement, and political attitudes."
    },
    {
      "title": "GESIS Panel.pop, Longitudinal Survey Data",
      "url_or_doi": "https://access.gesis.org/dbk/52787",
      "justification": "GESIS Panel.pop provides longitudinal survey data from a probability-based sample of the German population. Its historical waves include studies conducted during the 2010s that address political participation, populism, democratic attitudes, and perceptions of political elites. Particularly relevant are survey components concerning populist attitudes in Germany in 2017 and attitudes toward political elites, immigrants, and democratic decision-making. The dataset supports individual-level analyses of political opinion formation."
    },
    {
      "title": "Comparative Study of Electoral Systems (CSES), Integrated Module Dataset",
      "url_or_doi": "https://cses.org/data-download/cses-integrated-module-dataset-imd/",
      "justification": "The CSES combines nationally representative election surveys from multiple countries, including Germany. Its integrated dataset includes German election studies from the 2010s and provides measures of electoral participation, party choice, political attitudes, democratic satisfaction, ideological positioning, and evaluations of political institutions. It is especially useful for comparing German voting behaviour and political attitudes with those of voters in other democracies."
    },
    {
      "title": "GLES Candidate Studies, 2013 and 2017",
      "url_or_doi": "https://www.gesis.org/en/gles/data-and-documentation",
      "justification": "The GLES Candidate Studies collect survey information from candidates participating in German federal elections. The 2013 and 2017 datasets provide opportunities to examine political ideology, policy preferences, political representation, and differences between political parties. Unlike general population surveys, these datasets focus on political elites and candidates, making them valuable for studying ideological congruence between voters and representatives and changes in German party politics."
    },
    {
      "title": "German Longitudinal Election Study (GLES), 2013 Candidate Study",
      "url_or_doi": "https://doi.org/10.4232/1.13089",
      "justification": "This study surveys candidates associated with major political parties competing in the 2013 German federal election. It provides information relevant to political representation, candidates' attitudes, party differences, and political positioning. The dataset is particularly useful for analysing ideological differences among candidates and exploring relationships between political elites, party competition, and the electoral environment in Germany during the early 2010s."
    },
    {
      "title": "Moderner Staat und lebendige Demokratie (Modern State and Living Democracy), 2016",
      "url_or_doi": "https://doi.org/10.4232/1.12786",
      "justification": "This German survey, conducted in October 2016, examines attitudes toward government, public administration, digitalisation, and democracy. It includes political and demographic variables such as party sympathy and attitudes toward political institutions. The dataset is relevant for studying perceptions of democratic governance, public-sector modernisation, and the relationship between political preferences and attitudes toward the state during the mid-2010s."
    },
    {
      "title": "Politbarometer Annual Surveys, 2010–2019",
      "url_or_doi": "https://www.gesis.org/en/elections/politbarometer",
      "justification": "GESIS provides annual cumulative Politbarometer datasets covering each year of the 2010s. These contain more detailed year-specific questions than the partial cumulative time-series dataset. Researchers can investigate political attitudes toward the Merkel government, party preferences, satisfaction with democracy, immigration policy, European integration, and other contemporary political issues. The annual datasets are especially suitable for studying public responses to specific events and policy debates."
    },
    {
      "title": "German General Social Survey (ALLBUS), Cumulative Dataset",
      "url_or_doi": "https://www.gesis.org/en/allbus",
      "justification": "The cumulative ALLBUS dataset harmonises repeated survey questions across multiple years, including surveys conducted between 2010 and 2018. It facilitates longitudinal comparisons of political attitudes, trust in institutions, democratic values, ideological orientations, and social attitudes. Researchers interested in the 2010s can restrict the dataset to the relevant survey years, making it particularly useful for studying political and social change in Germany."
    }
  ]
}
